/**
 *
 * DataTableTHead is a component that displays a thead inside a DataTable.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableTHead
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableTHead component.
 */
export type DataTableTHeadPassThroughType<E> = PassThroughType<DataTableTHeadInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableTHead component.
 */
export interface DataTableTHeadPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableTHeadPassThroughType<React.HTMLAttributes<HTMLTableSectionElement>>;
}
/**
 * Defines valid properties in DataTableTHead component.
 */
export interface DataTableTHeadProps extends BaseComponentProps<DataTableTHeadInstance, unknown, DataTableTHeadPassThrough, 'thead'> {
}
/**
 * Defines valid state in DataTableTHead component.
 */
export interface DataTableTHeadState {
}
/**
 * Defines the methods and properties exposed by DataTableTHead component.
 */
export interface DataTableTHeadExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableTHead component.
 */
export type DataTableTHeadInstance = ComponentInstance<DataTableTHeadProps, DataTableTHeadState, DataTableTHeadExposes>;
